SELECT orderItem.* , orderMain.order_no AS orderNo , dishInfo.dish_name AS dishName2 , dishInfo.dish_img AS dishImg FROM order_item orderItem LEFT JOIN order_main orderMain ON orderItem.order_id = orderMain.id LEFT JOIN dish_info dishInfo ON orderItem.dish_id = dishInfo.id WHERE orderItem.order_id IN
#{id}
ORDER BY orderItem.create_time DESC
